function newOfficer(r,ech){var fem=NMS.fem>0&&r()<NMS.fem,o={name:personName(r,undefined,fem),cmd:3+Math.floor(r()*6),tac:3+Math.floor(r()*6),ini:3+Math.floor(r()*6),agg:3+Math.floor(r()*6),exp:Math.floor(r()*8),q:[]};
  var nq=r()<0.55?1:r()<0.5?2:0;for(var i=0;i<nq;i++){var k=QK[Math.floor(r()*QK.length)][0];if(o.q.indexOf(k)<0&&!(k==='careful'&&o.q.indexOf('reckless')>=0)&&!(k==='reckless'&&o.q.indexOf('careful')>=0)&&!(k==='staff'&&o.q.indexOf('slow')>=0)&&!(k==='slow'&&o.q.indexOf('staff')>=0))o.q.push(k);}
  o.rank=RANK[clamp(ech||1,0,8)];if(fem)o.f=1;return o;}
function hasQ(o,k){return !!(o&&o.q&&o.q.indexOf(k)>=0);}

