    var river=near(function(q){return lc[q]===LCI.riv||rv[q]>=3;},1500),coast=near(function(q){return lc[q]===LCI.sea||lc[q]===LCI.shal;},2500),railJ=year>=1860&&near(function(q){return rl[q]&1;},900),hillE=-1e9,hillK=c0;
