      var DN=NM.style==='west'?{old:'Old Town',port:'Docks',rly:'Station Quarter',ind:'Ironworks',sub:'New Town',cbd:'City Centre'}:{old:'舊城',port:'港區',rly:'車站區',ind:'工業區',sub:'新市區',cbd:'市中心'};
