  ['shock','mdef','ac','hard','arm','sig','mor','trn','dig'].forEach(function(k){o[k]=wsum?o[k]/wsum:0;});o.rE=wE?o.rE/wE:0;o.rM=wE?o.rM/wE:0;if(o.nv===9)o.nv=0;if(o.end>=1e9)o.end=0;o.dom=domOf(o.mobi);
