  if(!p)return false;p*=[1.6,1.3,1,0.6,0.3][profIdxOf(u)]*(optOf(u).post==='holdfast'?0.5:1)*(hasQ(off,'stubborn')?0.5:1)*(u.mor<10?2:1)*(/^(sup|hq|eng|art)$/.test(clsOf(u))?1.5:1);if(rnd()>p)return false;
