function lawEra(y){y=y===undefined?(G&&G.set?G.set.y:1943):y;var r=LAWERA[0];LAWERA.forEach(function(q){if(y>=lawRowY(q[0]))r=q;});return {y0:r[0],txt:r[1],minPow:r[2],minCiv:r[3],mul:r[4],dis:r[5]};}
