function polBase(u,k){var c=u,v;while(c){if(c.pol&&c.pol[k]!==undefined){v=c.pol[k];break;}c=c.p>=0?uById(c.p):null;}if(v===undefined)v=polSide(u.side)[k];return Math.max(v,lawMin(k));}
