/* ---------- 區域外飛彈精確打擊：射程外發射，飛行途中可能被防空與反飛彈系統攔截；同時來襲越多越容易突破（飽和） ---------- */
function mslSpec(u){var q=null;(u.mix||[]).forEach(function(m){var t=typeOf(m[0]),z=MSLT[m[0]]||(t&&t.msl);if(z&&(G.set.y||2000)>=(z.y0||0))q=z;});return q;}
