function rnd8(){if(!G._r8)G._r8=mb32(hstr((G.set.seed||'')+'|v8|'+Math.floor(G.t)));return G._r8();}
function featY(k){var o=G&&G.set&&G.set.featY,v=o?o[k]:undefined;return v!==undefined&&v!==null&&v!==''&&isFinite(+v)?+v:FEATD[k];}
