(function(){var b=v4Act;v4Act=function(u,o){if(v8Act(u,o))return true;return b(u,o);};})();
(function(){var b=v4Leaf;v4Leaf=function(u,s){if(v8Leaf(u,s))return true;return b(u,s);};})();
