/* ===================== 點數：
   一、部隊點數：只用來衡量雙方戰力（依火力、裝甲、訓練與現有兵力），不設限制；開戰後敵方只能依情報估計。
   二、增援點數（可開關）：所有增援與物資都要花——派遣增援、呼叫物資、從地圖外進入戰場的日常補給、休整時補充的兵員與裝備、
       工兵構築（陣地、工事、補給站、橋梁、渡口、道路與鐵路的修建）、擴充補給設施。每日固定配給一筆以維持日常補給；
       與敵人交戰的戰果、佔領與守住目標、把傷患與戰俘後送出地圖都會取得額外點數。
   三、科技點數（可開關）：開戰時本方已有與已經過時的武器不必解鎖；其他武器與裝備要用科技點數解鎖，才能配發、換裝或購買使用它們的單位。
   四、自訂增援範本：玩家自己組合的營、團、旅（單位類型與數量），可以匯出、匯入，戰中以增援派遣 ===================== */
function rpOn(){return !!(G&&G.set&&G.set.rp);}
function techOn(){return !!(G&&G.set&&G.set.tech);}
/* ---------- 一、部隊點數 ---------- */
function fpType(t){if(typeof t==='string')t=typeOf(t);if(!t)return 0;var base=(t.sa||0)+1.5*(t.ha||0)+0.8*(t.aa||0)+((t.ind||0)>0?0.4*(t.sa||0):0),prot=1+0.08*(t.arm||0)+0.3*(t.hard||0),q=0.6+0.4*clamp((t.trn||50)/70,0,1.3),m=t.dom==='air'?1.25:t.dom==='sea'||t.dom==='sub'?1.3:1;
  return Math.max(1,Math.round(10*base*prot*q*m+0.02*(t.men||0)+0.5*(t.veh||0)));}
function fpMix(mix){return (mix||[]).reduce(function(a,q){return a+fpType(q[0])*(q[1]||1);},0);}
function fpU(u){if(!u||!alive(u))return 0;if(!isLeaf(u)){var n=u.hq&&u.men0>0?fpType(u.hq)*clamp(u.men/u.men0,0,1):0;leavesOf(u).forEach(function(q){n+=fpU(q);});return Math.round(n);}
  var f=WF(u),wf=clamp(((f.p||1)+(f.a||1))/2,0.3,2);return Math.round(fpMix(u.mix)*wf*clamp(strFrac(u),0,1.2));}
function fpSide(side){var n=0;G.units.forEach(function(u){if(u.side!==side||!alive(u)||u.st==='off'||u.irr)return;if(isLeaf(u))n+=fpU(u);else if(u.hq&&u.men0>0)n+=fpType(u.hq)*clamp(u.men/u.men0,0,1);});return Math.round(n);}
/* 開戰後只能依情報估計敵方 */
function fpEst(side){var C=G.ct[side]||{},n=0;for(var id in C){var c=C[id];if(c.dead||G.t-c.t>6*3600)continue;n+=(c.men||0)*0.4+(c.veh||0)*9;}return Math.round(n);}
/* ---------- 二、增援點數 ---------- */
var RPWHY={start:'初始',day:'每日配給',fight:'交戰戰果',cap:'佔領目標',hold:'守住目標',evac:'後送傷患',pow:'後送戰俘',reinf:'增援',sup:'呼叫物資',flow:'日常補給（進入戰場）',build:'構築與建造',refit:'休整補充兵員裝備',node:'擴充補給設施',adj:'調整'};
function rpS(side){var S=SD(side);if(!S.rpx){var v0=G.set.rp0!==undefined&&G.set.rp0!==''&&isFinite(+G.set.rp0)?+G.set.rp0:800;S.rpx={v:v0,earn:0,spend:0,log:[{t:G.t||0,v:v0,why:'start',txt:''}],day:-1,by:{},ecas:-1,evl:-1,pow:-1,own:{}};}return S.rpx;}
function rpHave(side){return rpOn()?rpS(side).v:Infinity;}
function rpNote(R,amt,why,txt){var L=R.log,last=L[L.length-1];if(last&&last.why===why&&!txt&&!last.txt&&G.t-last.t<3600){last.v+=amt;return;}L.push({t:G.t,v:amt,why:why,txt:txt||''});if(L.length>80)L.splice(0,L.length-80);}
function rpAdd(side,amt,why,txt){if(!rpOn()||side<0||side>1||!(amt>0))return;var R=rpS(side);R.v+=amt;R.earn+=amt;R.by[why]=(R.by[why]||0)+amt;rpNote(R,amt,why,txt);}
/* 扣點：不足時回傳 false、不扣 */
function rpSpend(side,amt,why,txt){if(!rpOn()||!(amt>0))return true;var R=rpS(side);if(R.v+1e-6<amt)return false;R.v-=amt;R.spend+=amt;R.by[why]=(R.by[why]||0)-amt;rpNote(R,-amt,why,txt);return true;}
function rpDayAmt(side){var v=G.set.rpDay;if(v!==undefined&&v!==''&&v!=='auto'&&isFinite(+v))return Math.max(0,+v);var sm=logSummary(side),need=0;['food','ammo','fuel','fod'].forEach(function(c){need+=sm.need[c]||0;});return Math.round((need*0.6+250)/10)*10;}
function tpDayAmt(){var v=G.set.tpDay;return v!==undefined&&v!==''&&isFinite(+v)?Math.max(0,+v):20;}
function calDayL(){return Math.floor((G.t+(G.set.h||0)*3600+(G.set.mi||0)*60)/86400);}
/* 每 10 分鐘：每日配給、交戰戰果、目標、後送戰俘 */
var RPM={fightMan:0.12,fightVeh:2,cap:5,hold:0.25,evac:0.3,pow:0.5};
function rpStep(){if(!G.started||(!rpOn()&&!techOn()))return;var d=calDayL();
  [0,1].forEach(function(side){var R=rpS(side),T=tpS(side),e=1-side,ES=G.stats[e]||{},MS=G.stats[side]||{};
    if(R.day!==d){if(R.init){if(rpOn()){var a=rpDayAmt(side);rpAdd(side,a,'day');}if(techOn()){var ta=tpDayAmt();T.v+=ta;T.earn+=ta;}}R.day=d;R.init=1;}
    var cas=ES.cas||0,vl=ES.vl||0;if(R.ecas<0){R.ecas=cas;R.evl=vl;}var dc=cas-R.ecas,dv=vl-R.evl;R.ecas=cas;R.evl=vl;if(dc>0||dv>0){rpAdd(side,dc*RPM.fightMan+dv*RPM.fightVeh,'fight');if(techOn()){var tt=dc*0.01+dv*0.1;T.v+=tt;T.earn+=tt;}}
    var pe=MS.powEvac||0;if(R.pow<0)R.pow=pe;if(pe>R.pow){rpAdd(side,(pe-R.pow)*RPM.pow,'pow');R.pow=pe;}
    (G.obj||[]).forEach(function(ob){var was=R.own[ob.id],pts=ob.pts||10;if(ob.own===side&&was!==side&&was!==undefined){rpAdd(side,pts*RPM.cap,'cap','佔領「'+ob.name+'」');if(techOn()){T.v+=pts*0.5;T.earn+=pts*0.5;}}R.own[ob.id]=ob.own;
      if(ob.own===side){var threat=enemyNear(side,ob.x,ob.y,(ob.r||800)*2.5)>0;rpAdd(side,pts*RPM.hold/6*(threat?2:1),'hold');}});});}
/* 後送傷患：在醫療單位收治期滿、沒有歸隊的傷患後送出地圖 */
(function(){var b=medStep;medStep=function(){var snap=[];if(rpOn())G.units.forEach(function(m){if(m.pat&&m.pat.length)m.pat.forEach(function(p){snap.push([m.side,p,p.n]);});});b();
  snap.forEach(function(q){if(q[1].n===0&&q[2]>0.05)rpAdd(q[0],q[2]*0.65*RPM.evac,'evac');});};})();
/* 呼叫物資的費用：每噸糧彈油（陸路 1、鐵路 0.7、空運 3），武器每噸 20 */
var RPR={truck:1,wagon:1,porter:1,rail:0.7,ship:0.5,air:3,drop:3,heli:3},RPRF={truck:0.5,wagon:0.5,porter:0.5,rail:0.35,ship:0.25,air:1.5,drop:2,heli:2},RPW=20;
function supCost(legs){var c=0;legs.forEach(function(g){if(!g.n)return;var s=g.sc===undefined?1:g.sc;c+=(g.c.food+g.c.ammo+g.c.fuel)*s*(RPR[g.m]||1)+(g.wx?supWt(g.wx)*s*RPW:0);});return Math.ceil(c);}
function supPay(side,legs,m,opt){if(!rpOn())return '';var c=supCost(legs);if(!rpSpend(side,c,'sup',opt&&opt.route?'':null))return '增援點數不足（需要 '+fmt(c)+'，現有 '+fmt(Math.floor(rpHave(side)))+'）';opt._rp=c;return '';}
/* 日常補給：從地圖外進入戰場的物資送達時付費；點數不足時只收下付得起的部分 */
(function(){var b=lgUnloaded;lgUnloaded=function(V){if(!rpOn()||V.call||!V.src)return b(V);var srcOff=V.src.k==='edge'||V.src.k==='node'&&(lgNode(V.side,V.src.id)||{}).k==='off';if(!srcOff)return b(V);
  var side=V.side,rate=RPRF[V.m]||0.5,c0=lgCargo(V),aff=Math.max(0,rpS(side).v)/rate,cut=false;if(c0>0.01&&aff<c0){var f=aff/c0;LCLS.forEach(function(c){V.c[c]*=f;});cut=true;}
  var S=lgStats(side),t0=S.t,r=b(V),got=Math.max(0,S.t-t0);if(got>0){var R=rpS(side),amt=Math.min(R.v,got*rate);if(amt>0){R.v-=amt;R.spend+=amt;R.by.flow=(R.by.flow||0)-amt;rpNote(R,-amt,'flow');}}
  if(cut){var D=V.dst&&V.dst.k==='node'?lgNode(side,V.dst.id):null;if(D)D._lgWhy='增援點數不足，只收下部分物資';if(!R0cut[side]||G.t-R0cut[side]>6*3600){R0cut[side]=G.t;logE(side,'lgcut','增援點數不足：從地圖外進入的日常補給只收下約 '+pct(c0>0?aff/c0*100:0)+'，其餘退回後方');}}return r;};})();
var R0cut=[0,0];
/* 工兵構築與建造：開工時付費 */
var RPB={build:{pos:10,semi:30,fort:80,bastion:120,depot:60},bridge:60,xsite:{boat:10,raft:5,ferry:25},roadbuild:40,roadfix:8,railfix:15,repair:15};
function rpBuildCost(o){var c=RPB[o.k];if(c===undefined)return 0;if(typeof c==='object'){var key=o.k==='build'?(o.bk||(o.opt&&o.opt.bk)||'pos'):(o.xk||(o.opt&&o.opt.xk)||'boat');return c[key]||10;}return c;}
(function(){var b=activate;activate=function(u,o){if(rpOn()&&G.started&&o&&!o.rpPaid&&RPB[o.k]!==undefined&&u&&isLeaf(u)){var eng=typeof isEng!=='function'||isEng(u)||o.k==='xsite'||o.k==='roadfix';
    if(eng){var c=rpBuildCost(o);if(c>0){if(!rpSpend(u.side,c,'build',uName(u)+'：'+ordN(o))){if(!u._rpLowT||G.t-u._rpLowT>3600){u._rpLowT=G.t;logE(u.side,'cmd','增援點數不足（需要 '+c+'，現有 '+fmt(Math.floor(rpHave(u.side)))+'），'+uName(u)+'無法'+ordN(o),u.x,u.y,u.id);}return;}o.rpPaid=c;}}}
  return b(u,o);};})();
/* 休整：補充的兵員與裝備依部隊點數付費 */
(function(){var b=refitStep;refitStep=function(){if(!rpOn())return b();var snap=[];G.units.forEach(function(u){if(u.refit&&u.st==='off'&&isLeaf(u))snap.push([u,u.men,u.veh,u.trn,u.repl||0]);});var R0=SD(0).repl,R1=SD(1).repl;b();
  snap.forEach(function(q){var u=q[0],dm=Math.max(0,u.men-q[1]),dv=Math.max(0,u.veh-q[2]);if(dm<0.001&&dv<0.001)return;var w=(u.men0+u.veh0*8)||1,cost=fpMix(u.mix)*(dm+dv*8)/w*0.9;if(rpSpend(u.side,cost,'refit'))return;
    var R=rpS(u.side),aff=Math.max(0,R.v),f=cost>0?clamp(aff/cost,0,1):0;u.men=q[1]+dm*f;u.veh=q[2]+dv*f;u.trn=q[3];var back=dm*(1-f);if(back>0){SD(u.side).repl+=back;u.repl=q[4]+dm*f;}if(aff>0)rpSpend(u.side,aff,'refit');
    if(!u._rpLowR||G.t-u._rpLowR>6*3600){u._rpLowR=G.t;logE(u.side,'refit','增援點數不足，'+uName(u)+'的兵員與裝備補充暫停');}});void R0;void R1;};})();
/* 增援的費用：依部隊點數（滿編） */
function rpPresetCost(pk){var P=FPI[pk];if(!P)return 0;var n=fpMix(flatMix(pk,{})),hq=0;(function c(k){var Q=FPI[k];hq++;Q.kids.forEach(function(kd){if(kd[0].charAt(0)==='@')for(var i=0;i<kd[1];i++)c(kd[0].slice(1));});})(pk);return Math.round(n+hq*fpType(hqTypeFor(P.era)));}
function rpTypeCost(tk,n){return Math.round(fpType(tk)*(n||1));}
/* ---------- 三、科技點數 ---------- */
function tpS(side){var S=SD(side);if(!S.tpx){var v0=G.set.tp0!==undefined&&G.set.tp0!==''&&isFinite(+G.set.tp0)?+G.set.tp0:30;S.tpx={v:v0,unl:{},earn:0,log:[]};}return S.tpx;}
/* 不必解鎖：本方部隊開戰時已有的武器，以及本時代已經過時（早於 25 年）的武器 */
function techBase0(side){var o={},y=G.set.y||1943;Object.keys(WPNO).forEach(function(k){if((WPNO[k].y||0)<=y-25)o[k]=1;});G.units.forEach(function(u){if(u.side!==side)return;if(u.lg)(u.lg.w0||[]).concat(u.lg.w||[]).forEach(function(x){o[x[0]]=1;});else typesOfU(u).forEach(function(m){var t=typeOf(m[0]);if(t)((t.load||defLoad(t)).w||[]).forEach(function(x){o[x[0]]=1;});});});return o;}
function techBase(side){var S=SD(side);if(S.tbase)return S.tbase;var o=techBase0(side);if(G.started)S.tbase=o;return o;}
function techOK(side,k){if(!techOn()||side<0)return true;return !!(tpS(side).unl[k]||techBase(side)[k]);}
function techCost(k){var w=wpnOf(k);if(!w)return 999;var y=G.set.y||1943,c=wcls(k),mx=0;wpnList().forEach(function(q){if(wcls(q.k)===c&&(q.y||0)<=y)mx=Math.max(mx,wq(q.k));});mx=mx||wq(k)||1;
  return Math.max(5,Math.round(10+30*Math.min(1.5,wq(k)/mx)+(w.gen||0)*3+((w.y||0)>y?((w.y||0)-y)*4:0)));}
function techUnlock(side,k){var T=tpS(side),w=wpnOf(k);if(!w)return {err:'沒有這種武器'};if(techOK(side,k))return {err:'已經可以使用'};var c=techCost(k);if(T.v+1e-6<c)return {err:'科技點數不足（需要 '+c+'，現有 '+fmt(Math.floor(T.v))+'）'};
  T.v-=c;T.unl[k]=1;T.log.push({t:G.t,k:k,c:c});if(T.log.length>60)T.log.shift();logE(side,'log','科技：解鎖'+w.n+'（'+c+' 點）');return {ok:1,c:c};}
/* 單位類型需要哪些尚未解鎖的武器與裝備 */
function techTypeLock(side,tk){if(!techOn())return [];var t=typeOf(tk);if(!t)return [];return ((t.load||defLoad(t)).w||[]).map(function(x){return x[0];}).filter(function(k,i,A){return A.indexOf(k)===i&&!techOK(side,k);});}
function techPresetLock(side,pk){if(!techOn()||!FPI[pk])return [];var o=[];flatMix(pk,{}).forEach(function(q){techTypeLock(side,q[0]).forEach(function(k){if(o.indexOf(k)<0)o.push(k);});});return o;}
/* ---------- 四、自訂增援範本 ---------- */
function rftOf(side){var S=SD(side);if(!S.rft)S.rft=[];return S.rft;}
function rftEra(T){var q=(T.items||[]).filter(function(z){return typeOf(z[0]);})[0],t=q?typeOf(q[0]):null;return t?t.era:'e1940';}
function rftCost(T){var n=0;(T.items||[]).forEach(function(q){if(typeOf(q[0]))n+=fpType(q[0])*Math.max(0,+q[1]||0);});if(T.hq!==0)n+=fpType(hqTypeFor(rftEra(T)));return Math.round(n);}
function rftLock(side,T){var o=[];(T.items||[]).forEach(function(q){techTypeLock(side,q[0]).forEach(function(k){if(o.indexOf(k)<0)o.push(k);});});return o;}
function rftBuild(side,T,name,parent,r){var era=rftEra(T),ech=clamp(+T.ech||2,1,6);NMS.side=side;NMS.fem=offFem(side,era);var F=newUnit(side,{name:name||T.n||'自訂部隊',p:parent,ech:ech,hq:hqTypeFor(era),off:newOfficer(r,ech)});initStrength(F);if(parent>=0&&uById(parent))uById(parent).kids.push(F.id);
  (T.items||[]).forEach(function(q){var t=typeOf(q[0]);if(!t)return;for(var i=1;i<=Math.min(60,Math.max(0,Math.round(+q[1]||0)));i++){var L=newUnit(side,{name:'第'+i+t.n,p:F.id,ech:1,mix:[[q[0],1]],off:null});initStrength(L);F.kids.push(L.id);}});return F;}
var RFTFMT='LatoWarReinf';
function rftExport(L){return {format:RFTFMT,v:1,saved:new Date().toISOString(),templates:(L||[]).map(function(T){return {n:T.n,ech:T.ech,hq:T.hq===0?0:1,items:(T.items||[]).map(function(q){return [q[0],Math.max(0,Math.round(+q[1]||0))];})};})};}
function rftImport(side,D){if(!D||D.format!==RFTFMT||!Array.isArray(D.templates))return {err:'這不是增援範本檔（'+RFTFMT+'）'};var L=rftOf(side),n=0,skip=[];
  D.templates.forEach(function(T){if(!T||!Array.isArray(T.items))return;var items=T.items.filter(function(q){if(Array.isArray(q)&&typeOf(q[0]))return true;if(Array.isArray(q))skip.push(String(q[0]));return false;}).map(function(q){return [q[0],clamp(Math.round(+q[1]||0),0,60)];}).filter(function(q){return q[1]>0;});
    if(!items.length)return;L.push({id:'r'+(Date.now().toString(36))+n,n:String(T.n||'匯入範本').slice(0,60),ech:clamp(+T.ech||2,1,6),hq:T.hq===0?0:1,items:items});n++;});return {n:n,skip:skip};}
/* ---------- 五、增援名單（白名單／黑名單）與共用範本 ----------
   G.set.rfL＝[藍方名單, 紅方名單]，名單 {m:'off'|'white'|'black', b:[兵種], t:[單位類型], p:[編制範本]}：白名單只允許勾選的項目，黑名單禁止它們。
   編制範本與自訂範本要看裡面的每一種單位；在白名單直接勾選的編制範本一律允許。只管戰中增援（含 AI 購買），不影響開戰前的兵力。
   G.set.rfX：聯機時伺服器送來的共用範本（src 's' 管理員的伺服器範本、'r' 房主的房間範本），唯讀；G.set.rfH：管理員停用的內建編制範本 */
var RFLFMT='LatoWarReinfList';
function rflOf(side){var L=G&&G.set&&G.set.rfL;L=L&&L[side];return L&&(L.m==='white'||L.m==='black')?L:null;}
function rflType(side,tk){var L=rflOf(side);if(!L)return true;var t=typeOf(tk);if(!t)return false;var hit=(L.t||[]).indexOf(tk)>=0||(L.b||[]).indexOf(t.br)>=0;return L.m==='white'?hit:!hit;}
function rflHid(pk){return ((G&&G.set&&G.set.rfH)||[]).indexOf(pk)>=0;}
function rflPreset(side,pk){if(!FPI[pk]||rflHid(pk))return false;var L=rflOf(side);if(!L)return true;if((L.p||[]).indexOf(pk)>=0)return L.m==='white';return flatMix(pk,{}).every(function(q){return rflType(side,q[0]);});}
function rflBad(side,T){return (T&&T.items||[]).filter(function(q){return typeOf(q[0])&&q[1]>0&&!rflType(side,q[0]);}).map(function(q){return q[0];});}
function rflTpl(side,T){return !rflBad(side,T).length;}
function rftShared(){var X=G&&G.set&&G.set.rfX;return Array.isArray(X)?X:[];}
function rftAll(side){return rftOf(side).concat(rftShared());}
function rftFind(side,id){if(!id)return null;return rftAll(side).filter(function(q){return q.id===id;})[0]||null;}
/* 派遣前的名單檢查：允許時回傳空字串，否則回傳原因 */
function rflWhy(side,src,o){o=o||{};if(src==='preset'){if(rflHid(o.pk))return '這個編制範本已被伺服器管理員停用。';return rflPreset(side,o.pk)?'':'增援名單不允許這個編制範本（'+((FPI[o.pk]||{}).n||o.pk)+'）。';}
  if(src==='rft'){var bad=rflBad(side,o.T);return bad.length?'增援名單不允許範本中的：'+bad.map(function(k){return typeOf(k).n;}).join('、'):'';}
  return rflType(side,o.tk)?'':'增援名單不允許「'+((typeOf(o.tk)||{}).n||o.tk)+'」。';}
function rflClean(L){L=L||{};var f=function(A,n){return Array.isArray(A)?A.filter(function(x,i){return typeof x==='string'&&x.length<=60&&A.indexOf(x)===i;}).slice(0,n):[];};return {m:L.m==='white'||L.m==='black'?L.m:'off',b:f(L.b,80),t:f(L.t,800),p:f(L.p,800)};}
function rflExport(lists){return {format:RFLFMT,v:1,saved:new Date().toISOString(),lists:[0,1].map(function(s){return rflClean(lists&&lists[s]);})};}
function rflImport(D){if(!D||D.format!==RFLFMT||!Array.isArray(D.lists))return {err:'這不是增援名單檔（'+RFLFMT+'）'};return {lists:[0,1].map(function(s){return rflClean(D.lists[s]);})};}
function rflTxt(side){var L=rflOf(side);if(!L)return '不限制';var n=(L.b||[]).length+(L.t||[]).length+(L.p||[]).length;return (L.m==='white'?'白名單：只允許 ':'黑名單：禁止 ')+n+' 項';}
/* 派遣增援（介面與 AI 共用）：扣點後建立部隊，指定時間從地圖邊緣或指定地點進場 */
function rpReinfCost(src,o){return src==='preset'?rpPresetCost(o.pk):src==='rft'?rftCost(o.T):rpTypeCost(o.tk,o.n);}
/* AI：兵力居於劣勢、點數足夠時購買一個營（或連）的增援 */
function rpAI(){if(!rpOn())return;[0,1].forEach(function(side){var S=SD(side);if(!S.ai)return;var R=rpS(side);if(R.v<300||G.t-(S._rpBuyT||-1e9)<3*3600)return;var hq=sideCmd(side),era=hq?uEra(hq).k:null;if(!era)return;
  var me=sideStr(side),en=sideStr(1-side);if(me.m>en.m*1.15&&R.v<1500)return;
  var L=FP.filter(function(p){return p.era===era&&p.ech>=1&&p.ech<=2;}).map(function(p){return [p,rpPresetCost(p.k)];}).filter(function(q){return q[1]>0&&q[1]<=R.v*0.7&&!techPresetLock(side,q[0].k).length&&rflPreset(side,q[0].k);}).sort(function(a,b){return b[1]-a[1];});if(!L.length)return;
  var pick=L[Math.floor(rnd8()*Math.min(3,L.length))],P=pick[0];if(!rpSpend(side,pick[1],'reinf',P.n))return;S._rpBuyT=G.t;var par=hq&&!isLeaf(hq)?hq.id:-1,u=buildPreset(side,P.k,null,par,mb32(hstr('rpai|'+side+'|'+G.t)),'co',null);reix();
  (function w(z){logInit(z);z.ms='ok';z.form='deployed';z.task='hold';z.sup=0;z.fat=0;z.st='off';z.ammo=100;kidsOf(z).forEach(w);})(u);var e=edgePoint(side,0.3+0.4*rnd8()),ob=(G.obj||[])[0],tx=ob?ob.x:G.map.Wm/2,ty=ob?ob.y:G.map.Hm/2;
  u.arr={k:'time',t:G.t+1800,x:e[0],y:e[1],mode:'edge',ord:{k:'reserve',x:e[0]+(tx-e[0])*0.3,y:e[1]+(ty-e[1])*0.3}};dupNames();logE(side,'reinf','以 '+fmt(pick[1])+' 增援點數派遣增援 '+uName(u)+'，約 30 分鐘後抵達',e[0],e[1],u.id);});}
(function(){var b=v8Step;v8Step=function(){b();if(G.step%20===19)rpStep();if(G.step%120===61)rpAI();};})();

/* ==== h37_dir.js ==== */
/* ===================== 戰略決策：在沙盒（看 AI 對戰）或上帝視角下，在地圖上放置進攻、防禦、死守、設防、建設、偵察、火力打擊、集結等決策。
   電腦指揮官依優先等級抽調部隊執行（優先等級越高投入越多），回報兵力是否足夠；執行中的部隊暫時不受其他 AI 計畫調動，
   完成（攻佔、構築完成、抵達偵察區）、期限到或失去戰鬥力時回報並交還指揮。玩家仍可以直接下令覆蓋 ===================== */
var DIRK={attack:['進攻','⚔'],defend:['防禦','⛨'],hold:['死守','⛊'],fortify:['設防','▦'],build:['建設','⚒'],recon:['偵察','◉'],fire:['火力打擊','✸'],rally:['集結','◎']};
var DIRSUB={depot:'補給站',bridge:'橋梁',road:'道路',fort:'堡壘工事'};
var DIRST={new:'待執行',active:'執行中',done:'完成',fail:'無法執行',cancel:'已取消'};
var DIRSIM=0,DIRX=0;
function dirList(){return G.dirs||(G.dirs=[]);}
function dirById(id){var L=G.dirs||[];for(var i=0;i<L.length;i++)if(L[i].id===id)return L[i];return null;}
function dirActive(D){return !!D&&(D.st==='new'||D.st==='active');}
/* 指揮官的回報 */
function dirSay(side,txt,x,y){var top=sideCmd(side),who=top&&top.off?top.off.rank+top.off.name:G.sides[side].name+'司令部';logE(side,'ai',who+'（戰略決策）：'+txt,x,y);if(typeof decLog==='function')decLog(side,who,txt,{});}
function dirAdd(side,o){var L=dirList(),k=DIRK[o.k]?o.k:'attack',D={id:(G.dirSeq=(G.dirSeq||0)+1),side:side,k:k,sub:k==='build'?(DIRSUB[o.sub]?o.sub:'depot'):'',x:o.x,y:o.y,r:clamp(+o.r||1500,300,8000),pri:clamp(Math.round(+o.pri||2),1,3),prep:o.prep?1:0,dur:Math.max(0,+o.dur||0),t0:G.t,st:'new',gs:[],eng:[],tk:-1e9,msg:'',by:o.by||'user'};
  L.push(D);if(L.length>100)L.splice(0,L.length-100);logE(side,'cmd','戰略決策：'+dirNm(D)+'——'+placeTxt(D.x,D.y)+'（優先等級 '+D.pri+(D.dur?'，期限 '+D.dur+' 小時':'')+'）',D.x,D.y);if(SD(side).ai)dirExec(D);return D;}
function dirNm(D){return DIRK[D.k][0]+(D.sub?'（'+DIRSUB[D.sub]+'）':'');}
function dirRelease(D){(D.gs||[]).concat(D.eng||[]).forEach(function(id){var u=uById(id);if(u&&u.dirId===D.id)u.dirId=0;});}
function dirCancel(D,why){if(!dirActive(D))return;D.st='cancel';D.t1=G.t;dirRelease(D);logE(D.side,'cmd','取消戰略決策：'+dirNm(D)+'（'+placeTxt(D.x,D.y)+'）'+(why?'：'+why:''),D.x,D.y);}
function dirEnd(D,st,why){if(!dirActive(D))return;D.st=st;D.t1=G.t;D.msg=why||'';
  if(st==='done'&&D.k==='attack'){DIRX++;try{D.gs.forEach(function(id){var g=uById(id);if(g&&alive(g))issue(g,'defend',{x:D.x,y:D.y,face:dirFace(D),opt:{post:'hasty'},dirId:D.id});});}finally{DIRX--;}}
  dirRelease(D);dirSay(D.side,'「'+dirNm(D)+'」（'+placeTxt(D.x,D.y)+'）'+(st==='done'?'完成':'無法繼續')+(why?'：'+why:''),D.x,D.y);}
/* 鎖定：執行決策的編組（本身或上級）暫時不受其他 AI 計畫調動 */
function dirLockOf(u){var x=u,n=0;while(x&&n++<12){if(x.dirId){var D=dirById(x.dirId);if(dirActive(D))return D;x.dirId=0;}x=x.p>=0?uById(x.p):null;}return null;}
function dirFace(D){var ec=enemyCentroid(D.side,D.x,D.y,30000);return ec?Math.atan2(ec[1]-D.y,ec[0]-D.x):homeDir(D.side)+PI;}
function dirPos(g){var c=cOf(g);return c||[g.x,g.y];}
function dirStr(g){var L=isLeaf(g)?[g]:leavesOf(g).filter(onMap);return L.reduce(function(a,u){return a+u.men+u.veh*8;},0);}
function dirKnownEnemy(side,x,y,R,age){var C=G.ct[side]||{},n=0;for(var id in C){var c=C[id];if(c.dead||G.t-c.t>(age||3600)||c.dom==='air'||c.dom==='sea'||c.dom==='sub')continue;if(dist(c.x,c.y,x,y)<=R)n+=(c.men||0)+(c.veh||0)*8;}return n;}
/* 可以抽調的機動部隊（電腦指揮、未被其他決策占用） */
function dirMan(side){return aiGroups(side).filter(function(g){if(!alive(g)||g.st==='off'||g.irr||!aiControls(g)||dirLockOf(g))return false;var r=roleOf(g);if(r!=='man'&&r!=='rec')return false;var L=isLeaf(g)?[g]:leavesOf(g).filter(onMap);if(!L.length||L.filter(isEng).length>L.length/2)return false;return L.some(function(u){return ST(u).dom==='land';});});}
function dirLeaves(side,f){var o=[];G.units.forEach(function(u){if(u.side!==side||!isLeaf(u)||!onMap(u)||!aiControls(u)||u.ms==='rout'||dirLockOf(u))return;if(f(u))o.push(u);});return o;}
function dirTake(D,arr,n,score){return arr.map(function(g){return [g,score(g)];}).sort(function(a,b){return a[1]-b[1];}).slice(0,n).map(function(q){return q[0];});}
function dirN(L,pri){return L.length?clamp(Math.round(L.length*[0.2,0.35,0.5][pri-1]),1,Math.max(1,L.length-(pri<3&&L.length>1?1:0))):0;}
function dirOrd(D,u,k,p){p=p||{};p.dirId=D.id;u.dirId=D.id;u.dirIss=G.t;DIRX++;try{issue(u,k,p);}finally{DIRX--;}}
/* 抽調部隊並下令 */
function dirExec(D){if(!dirActive(D)||!SD(D.side).ai)return;var side=D.side,x=D.x,y=D.y,face=dirFace(D),names=[],k=D.k;
  var man=function(n){var L=dirMan(side);return dirTake(D,L,dirN(L,D.pri)*(n||1),function(g){var p=dirPos(g);return dist(p[0],p[1],x,y)/1000-(k==='attack'?strFrac(isLeaf(g)?g:(leavesOf(g)[0]||g))*6:0)+(roleOf(g)==='rec'?60:0);});};
  var eng=function(n){return dirTake(D,dirLeaves(side,function(u){return isEng(u);}),n,function(u){return dist(u.x,u.y,x,y);});};
  if(k==='attack'||k==='defend'||k==='hold'||k==='rally'){var gs=man();if(!gs.length){dirEnd(D,'fail','沒有可以抽調的機動部隊');return;}
    gs.forEach(function(g){if(k==='attack')dirOrd(D,g,'attack',{x:x,y:y,opt:D.prep?{prep:20}:{}});else if(k==='defend')dirOrd(D,g,'defend',{x:x,y:y,face:face,opt:{post:'prepared'}});else if(k==='hold')dirOrd(D,g,'holdfast',{x:x,y:y,face:face});else dirOrd(D,g,'reserve',{x:x,y:y});names.push(uName(g));});D.gs=gs.map(function(g){return g.id;});
    var mine=gs.reduce(function(a,g){return a+dirStr(g);},0),en=dirKnownEnemy(side,x,y,D.r*2),warn=k==='attack'&&en>mine*0.9?'；已知敵軍約為我方的 '+fmt(en/Math.max(1,mine),1)+' 倍，攻擊恐怕難以奏效':k!=='attack'&&k!=='rally'&&en>mine*1.5?'；附近敵軍兵力占優，可能守不住':'';
    dirSay(side,'遵命，派'+names.slice(0,4).join('、')+(names.length>4?'等 '+names.length+' 個單位':'')+(k==='attack'?'進攻':k==='defend'?'防守':k==='hold'?'死守':'集結於')+placeTxt(x,y)+(D.prep&&k==='attack'?'，先實施火力準備':'')+warn,x,y);}
  else if(k==='fortify'||k==='build'){var E=eng(k==='fortify'?D.pri:Math.min(2,D.pri));if(!E.length){dirEnd(D,'fail','沒有可以派出的工兵');return;}
    var bk=k==='fortify'?(D.pri>=3?'fort':D.pri>=2?'semi':'pos'):D.sub==='fort'?'fort':'depot';
    E.forEach(function(u,i){var ox=x+(i%2?1:-1)*Math.ceil(i/2)*300,oy=y;if(k==='build'&&D.sub==='bridge')dirOrd(D,u,'bridge',{x:x,y:y});else if(k==='build'&&D.sub==='road')dirOrd(D,u,'roadbuild',{x:x,y:y});else dirOrd(D,u,'build',{x:ox,y:oy,bk:bk,face:face});names.push(uName(u));});D.eng=E.map(function(u){return u.id;});
    if(k==='fortify'){var g=man(1)[0];if(g){dirOrd(D,g,'defend',{x:x,y:y,face:face,opt:{post:'prepared'}});D.gs=[g.id];names.push(uName(g)+'（掩護）');}}
    dirSay(side,'遵命，派'+names.join('、')+(k==='fortify'?'在'+placeTxt(x,y)+'構築'+BLD[bk][0]:'在'+placeTxt(x,y)+'建設'+DIRSUB[D.sub]),x,y);}
  else if(k==='recon'){var R=dirTake(D,dirLeaves(side,function(u){var s=ST(u);return s.dom==='land'&&(s.fl.indexOf('r')>=0||roleOf(u)==='rec');}),D.pri,function(u){return dist(u.x,u.y,x,y);});
    if(!R.length)R=dirTake(D,dirLeaves(side,function(u){return ST(u).dom==='land'&&roleOf(u)==='man'&&u.men<=250;}),1,function(u){return dist(u.x,u.y,x,y);});if(!R.length){dirEnd(D,'fail','沒有可以派出的偵察部隊');return;}
    R.forEach(function(u){dirOrd(D,u,'recon',{x:x,y:y});names.push(uName(u));});D.gs=R.map(function(u){return u.id;});dirSay(side,'遵命，派'+names.join('、')+'偵察'+placeTxt(x,y),x,y);}
  else if(k==='fire'){var A=dirTake(D,dirLeaves(side,function(u){var s=ST(u);return s.dom==='land'&&(s.ind||0)>0&&dist(u.x,u.y,x,y)<=(s.ind||0)*0.95&&u.ammo>15;}),D.pri*2,function(u){return dist(u.x,u.y,x,y);});
    if(!A.length){dirEnd(D,'fail','射程內沒有可用的砲兵');return;}A.forEach(function(u){dirOrd(D,u,'bombard',{x:x,y:y});names.push(uName(u));});D.gs=A.map(function(u){return u.id;});D.tk=G.t;if(!D.dur)D.dur=3;dirSay(side,'遵命，'+names.slice(0,4).join('、')+(names.length>4?'等 '+names.length+' 個砲兵單位':'')+'對'+placeTxt(x,y)+'實施火力打擊',x,y);}
  D.st='active';D.ta=G.t;}
/* 每 10 分鐘檢查：完成條件、補充命令、失去戰鬥力 */
/* 攻佔：派出的部隊進入核心區（半徑六成）並站穩 15 分鐘，而且兩小時內沒有在區內看到敵軍 */
function dirCleared(D){var inside=D.gs.some(function(id){var g=uById(id);if(!g)return false;return (isLeaf(g)?[g]:leavesOf(g).filter(onMap)).some(function(u){return roleOf(u)!=='rec'&&dist(u.x,u.y,D.x,D.y)<=D.r*0.6;});});
  if(!inside||dirKnownEnemy(D.side,D.x,D.y,D.r,7200)>0){D.occ=0;return false;}if(!D.occ)D.occ=G.t;return G.t-D.occ>=900;}
function dirTick(){var L=G.dirs;if(!L||!L.length)return;L.forEach(function(D){if(!dirActive(D)||!SD(D.side).ai)return;if(D.st==='new'){dirExec(D);return;}
  if(D.dur>0&&G.t-D.t0>D.dur*3600){dirEnd(D,'done','期限已到');return;}
  D.gs=D.gs.filter(function(id){var g=uById(id);return g&&alive(g)&&g.dirId===D.id&&dirStr(g)>0;});D.eng=D.eng.filter(function(id){var u=uById(id);return u&&alive(u)&&u.dirId===D.id;});var k=D.k;
  if(k==='attack'){if(dirCleared(D)){dirEnd(D,'done','已攻佔，轉入防禦');return;}if(!D.gs.length){dirEnd(D,'fail','攻擊部隊已失去戰鬥力');return;}}
  else if(k==='fortify'||k==='build'){var busy=D.eng.some(function(id){var u=uById(id);return u&&u.ord&&u.ord.dirId===D.id;});if(busy)D.seen=1;
    if(!D.eng.length){dirEnd(D,'fail','工兵已失去戰鬥力');return;}if(!busy&&D.seen){dirEnd(D,'done',k==='fortify'?'工事構築完成':DIRSUB[D.sub]+'建設完成');return;}if(!busy&&!D.seen&&G.t-D.ta>2*3600){dirEnd(D,'fail','工兵沒有接到命令');return;}}
  else if(k==='recon'){var seen=D.gs.some(function(id){var u=uById(id);return u&&dist(u.x,u.y,D.x,D.y)<=D.r;});if(seen&&G.t-D.ta>600){var en=dirKnownEnemy(D.side,D.x,D.y,D.r*1.5);dirEnd(D,'done',en>0?'發現約 '+fmt(en)+' 名敵軍（含裝備折算）':'未發現敵軍');return;}if(!D.gs.length){dirEnd(D,'fail','偵察部隊已失去戰鬥力');return;}}
  else if(k==='fire'){if(!D.gs.length){dirEnd(D,'fail','砲兵已無法射擊');return;}if(G.t-D.tk>=3600){D.tk=G.t;D.gs.forEach(function(id){var u=uById(id);if(u&&u.ammo>10)dirOrd(D,u,'bombard',{x:D.x,y:D.y});});}return;}
  else if(!D.gs.length){dirEnd(D,'fail','部隊已失去戰鬥力');return;}
  /* 補充命令：被打斷或偏離目標時重新下令 */
  var want=k==='attack'?'attack':k==='defend'?'defend':k==='hold'?'defend':k==='rally'?'reserve':k==='fortify'?'defend':null;if(!want)return;
  /* 只有在命令被別的命令取代、或部隊閒置超過一小時時才重下（每次重下都要重新參謀規劃） */
  D.gs.forEach(function(id){var g=uById(id);if(!g||G.t-(g.dirIss||0)<2*3600)return;var o=g.ord;if(o&&o.dirId===D.id)return;var busy=(isLeaf(g)?[g]:leavesOf(g).filter(onMap)).some(function(u){return u.ord&&u.ord.dirId===D.id;});if(busy)return;
    if(!o){if(!g.dirIdle)g.dirIdle=G.t;if(G.t-g.dirIdle<3600)return;}g.dirIdle=0;
    if(k==='attack')dirOrd(D,g,'attack',{x:D.x,y:D.y,opt:{}});else if(k==='hold')dirOrd(D,g,'holdfast',{x:D.x,y:D.y,face:dirFace(D)});else if(k==='rally')dirOrd(D,g,'reserve',{x:D.x,y:D.y});else dirOrd(D,g,'defend',{x:D.x,y:D.y,face:dirFace(D),opt:{post:'prepared'}});});});}
/* ---------- 鎖定：其他 AI 計畫不得調動執行決策的部隊（玩家直接下令不受限） ---------- */
var DIRMOV={move:1,attack:1,defend:1,withdraw:1,reserve:1,storm:1,breakthrough:1,penetrate:1,pursue:1,screen:1,patrol:1,recon:1,siege:1,holdfast:1,delay:1,ambush:1,halt:1,rest:1,joint:1,bombard:1,support:1};
(function(){var b=simStep;simStep=function(){DIRSIM++;try{return b.apply(this,arguments);}finally{DIRSIM--;}};})();
(function(){var b=issue;issue=function(u,k,p){if(DIRSIM>0&&!DIRX&&u&&G.dirs&&G.dirs.length&&!(p&&p.dirId)){var D=dirLockOf(u);if(D&&(DIRMOV[k]||D.k==='fortify'||D.k==='build')&&SD(u.side).ai&&aiControls(u))return {sec:0,dirBlocked:D.id};}return b(u,k,p);};})();
(function(){var b=receiveOrder;receiveOrder=function(u,o){if(DIRSIM>0&&!DIRX&&u&&o&&!o.dirId&&G.dirs&&G.dirs.length){var D=dirLockOf(u);if(D&&(DIRMOV[o.k]||D.k==='fortify'||D.k==='build')&&SD(u.side).ai&&aiControls(u))return;}return b(u,o);};})();
(function(){var b=planOrder;planOrder=function(F,o){var r=b(F,o);if(!G.dirs||!G.dirs.length||!Array.isArray(r))return r;var DF=dirLockOf(F);r=r.filter(function(q){var u=q&&q[0];if(!u)return true;var D=dirLockOf(u);return !D||D===DF;});
  /* 決策命令往下傳時保留標記 */if(o&&o.dirId)r.forEach(function(q){if(q&&q[1]&&!q[1].dirId)q[1].dirId=o.dirId;});return r;};})();
(function(){var b=aiGroups;aiGroups=function(side){var L=b(side);if(!G.dirs||!G.dirs.length)return L;return L.filter(function(g){return !dirLockOf(g);});};})();
(function(){var b=v8Step;v8Step=function(){b();if(G.step%20===7)dirTick();};})();

/* ==== h38_cbrn.js ==== */
/* ===================== 化學、生物、放射性（CBRN）作戰：
   毒劑雲隨風漂移、擴散、被雨沖淡，重於空氣的毒劑沉入低地與壕溝；持久性毒劑（芥子氣、VX、炭疽孢子、放射性落塵、魔瘴）污染地面，經過或停留的部隊持續暴露並沾染裝備。
   防護：防毒面具（聞到或警報後戴上，有延遲）、防護服與防護等級（MOPP 0～4，越高越安全但越累、戰鬥力越低）、密閉載具、疫苗（天花、鼠疫、炭疽；異世界的祝福）。
   應對：工兵與醫療單位除污、醫療單位接種疫苗、隔離傳染病患。古代可以拋射疫屍，異世界有魔瘴。使用化學與生物武器依年代記為違反國際法（1899 海牙宣言、1925 日內瓦議定書）。
   風：G.env.wd（風吹向的方向）、G.env.ws（公尺／秒），隨天氣緩慢變化 ===================== */
/* 毒劑：[名稱, 類別 c化學 b生物 r放射 m魔法, 年代, 殺傷 k（每單位劑量）, 致死比例, 地面持久（小時）, 雲存續（分鐘）, 重於空氣, 面具防護, 防護服防護, 疾病, 顏色] */
var CBA={chl:['氯氣','c',1915,0.9,0.1,0,50,1,0.85,0.2,'','#c8d24a'],phos:['光氣','c',1916,1.2,0.22,0,50,1,0.9,0.2,'','#d9e8b0'],must:['芥子氣','c',1917,0.5,0.03,72,90,1,0.45,0.9,'','#b0893a'],
  sarin:['沙林（神經毒劑）','c',1950,2.2,0.55,3,35,0,0.75,0.6,'','#9b7fd1'],vx:['VX（持久性神經毒劑）','c',1960,2.6,0.6,240,45,0,0.4,0.92,'','#7a4fb5'],
  anth:['炭疽孢子','b',1940,0.6,0,700,90,0,0.95,0.6,'anth','#8a6e4b'],plag:['鼠疫菌','b',1940,0.5,0,0,60,0,0.85,0.4,'plag','#6e5a3a'],pox:['天花病毒','b',1940,0.4,0,0,60,0,0.75,0.3,'pox','#a0522d'],
  corpse:['疫屍（拋射）','b',0,0.3,0,24,25,0,0.3,0.1,'plag','#5b4636'],dirty:['放射性髒彈','r',1950,0.25,0.3,4000,120,0,0.5,0.3,'','#d81b60'],mias:['魔瘴','m',0,0.7,0.2,48,150,1,0.5,0.4,'mias','#6a1b9a']};
var CBT={c:'化學',b:'生物',r:'放射性',m:'魔法'};
KIAF.gas=0.08;KIAF.nerve=0.6;KIAF.mias=0.3;
if(typeof DZ!=='undefined'){DZ.anth=['炭疽',0,0.45,0.12,7];DZ.mias=['魔瘴熱',0,0.3,0.06,6];}
var CBVX={pox:['天花疫苗',1798,7],plag:['鼠疫疫苗',1897,10],anth:['炭疽疫苗',1954,14],mias:['淨化祝福',0,1]};
var CBC={pox:1,plag:1,mias:1};/* 會人傳人 */
var CBINC={};/* 自訂疾病的潛伏期（天） */
function cbOn(){return !G||!G.set||G.set.cbrn!==false;}
function cbFan(side){var hq=sideCmd(side);return !!(hq&&uEra(hq).fan);}
function cbY(side){var hq=sideCmd(side);return hq?uEra(hq).y:(G.set.y||1943);}
/* 這一方此時能用的毒劑 */
function cbAvail(side){var y=cbY(side),fan=cbFan(side);return Object.keys(CBA).filter(function(k){var a=CBA[k];if(k==='mias')return fan;if(k==='corpse')return !fan&&y<1900;return !fan&&y>=a[2];});}
/* 依年代的國際法 */
function cbLaw(ag){var y=G.set.y||1943,t=CBA[ag][1];if(t==='m')return '';if(t==='b'&&ag==='corpse')return '';if(y>=1925)return t==='r'?'1949 年日內瓦公約禁止不分青紅皂白攻擊平民（放射性污染無法區分軍民）':'1925 年日內瓦議定書禁止在戰爭中使用化學與生物武器'+(y>=1993&&t==='c'?'（1993 年化學武器公約全面禁止）':y>=1972&&t==='b'?'（1972 年生物武器公約全面禁止）':'');
  if(y>=1899&&t==='c')return '1899 年海牙宣言禁止使用以散布窒息性或有毒氣體為唯一目的的砲彈';return '';}
/* ---------- 風 ---------- */
function windInit(){var E=G.env;if(E.wd!==undefined)return;var r=mb32(hstr((G.set.seed||'')+'|wind'));E.wd=r()*2*PI;E.ws=2+r()*3;E.wsT=E.ws;}
/* 風用自己的亂數（不影響其他系統的亂數序列） */function windStep(){var E=G.env;windInit();var r=mb32(hstr((G.set.seed||'')+'|wd|'+G.step)),w=WX[E.wx]||WX[0],nm=String(w[1]||''),tgt=/暴|颱|風/.test(nm)?11:/雨|雪/.test(nm)?5.5:/霧/.test(nm)?1:3.2;E.wsT+=(tgt-E.wsT)*0.2;E.ws=clamp(E.ws+(E.wsT-E.ws)*0.3+(r()-0.5)*0.8,0.3,20);E.wd+=(r()-0.5)*0.35;}
var DIR8N=['東','東南','南','西南','西','西北','北','東北'];
function windTxt(){var E=G.env;if(E.wd===undefined)return '';var from=E.wd+PI,a=((from%(2*PI))+2*PI)%(2*PI);return DIR8N[Math.round(a/(PI/4))%8]+'風 '+fx(E.ws,1)+' 公尺／秒';}
/* ---------- 部隊的防護 ---------- */
function cbGear(u){if(u.cbg)return u.cbg;var y=uEra(u).y,fan=!!uEra(u).fan;u.cbg={mask:fan?0.5:y>=1916?1:y>=1915?0.5:0,suit:fan?0:y>=1960?1:y>=1940?0.35:y>=1917?0.1:0,filt:100,vax:{},on:0,inf:[],dose:0,cont:0};
  var V=SD(u.side).vax0||{};Object.keys(V).forEach(function(k){if(V[k])u.cbg.vax[k]=-1e9;});return u.cbg;}
function cbMopp(u){var g=u.cbg,m=SD(u.side).mopp||0;return u.mopp!==undefined?u.mopp:m;}
/* 防護係數：面具（已戴上）、防護服（依防護等級）、密閉載具、工事；重於空氣的毒劑沉入壕溝 */
function cbProt(u,ag){var g=cbGear(u),A=CBA[ag],s=ST(u),M=cbMopp(u),y=uEra(u).y,p=0,masked=g.on||M>=4;if(masked&&g.mask>0&&g.filt>0)p=A[8]*g.mask;var sp=g.suit*A[9]*(M>=4?1:M>=3?0.75:M>=2?0.5:0);p=1-(1-p)*(1-sp);
  if(s.arm>0&&u.veh>0){var veh=y>=1960?0.9:y>=1940?0.5:0.3;p=1-(1-p)*(1-veh*clamp(u.veh*8/(u.men+u.veh*8),0.3,1));}if(A[7]&&(u.ent||0)>0.5)p*=0.85;if(A[1]==='m'&&uEra(u).fan)p=Math.max(p,0.3);return clamp(p,0,0.98);}
/* ---------- 毒劑雲與地面污染 ---------- */
function cbList(){return G.cbx||(G.cbx=[]);}
function cbRelease(side,ag,x,y,mass,r,src,why){var L=cbList(),A=CBA[ag];if(!A)return null;var C=null;L.forEach(function(q){if(!C&&q.ag===ag&&dist(q.x,q.y,x,y)<q.r*0.5){C=q;}});
  if(C){C.m+=mass;C.x=(C.x*2+x)/3;C.y=(C.y*2+y)/3;C.r=Math.max(C.r,r);return C;}C={id:(G.cbSeq=(G.cbSeq||0)+1),ag:ag,x:x,y:y,r:r,m:mass,t0:G.t,side:side,src:src?src.id:0,seen:[side===0?1:0,side===1?1:0]};L.push(C);
  if(!G.cbUse)G.cbUse=[0,0];if(side>=0&&!G.cbUse[side]){G.cbUse[side]=G.t;}var law=cbLaw(ag);if(src&&law&&!src._cbLaw){src._cbLaw=1;if(typeof warCrime==='function')warCrime(src,'cbrn',0,'使用'+A[0]+'（'+placeTxt(x,y)+'）——'+law);}
  logE(side,'cbrn',(src?uName(src):G.sides[side]?G.sides[side].name:'')+(why||'施放')+A[0]+'（'+placeTxt(x,y)+'）',x,y,src?src.id:undefined);return C;}
function cbGK(x,y){var B=G.map.cs*8;return Math.floor(x/B)+'|'+Math.floor(y/B);}
function cbGround(){return G.cbgr||(G.cbgr={});}
/* 每 2 分鐘：雲漂移、擴散、衰減；持久性毒劑落地；部隊與平民暴露 */
function cbrnStep(){var L=G.cbx,GR=G.cbgr;if((!L||!L.length)&&(!GR||!Object.keys(GR).length)&&!cbAnyInf())return;windInit();var E=G.env,dt=120,w=WX[E.wx]||WX[0],rain=/雨|雪/.test(String(w[1]||'')),hot=E.T>25,MP=G.map;
  (L||[]).forEach(function(C){var A=CBA[C.ag],age=(G.t-C.t0)/60,ws=E.ws*(A[7]?0.7:1);C.x=clamp(C.x+Math.cos(E.wd)*ws*dt,0,MP.Wm);C.y=clamp(C.y+Math.sin(E.wd)*ws*dt,0,MP.Hm);
    if(A[7]){/* 重於空氣：往低處流 */var k=cellAt(C.x,C.y),gx=k%MP.GW,gy=(k/MP.GW)|0,best=MP.el[k],bx=0,by=0;for(var b=-2;b<=2;b++)for(var a=-2;a<=2;a++){var X=gx+a*2,Y=gy+b*2;if(X<0||Y<0||X>=MP.GW||Y>=MP.GH)continue;var e=MP.el[Y*MP.GW+X];if(e<best){best=e;bx=a;by=b;}}C.x+=bx*MP.cs*0.4;C.y+=by*MP.cs*0.4;}
    var r0=C.r;C.r=Math.min(6000,C.r+(0.25+E.ws*0.05)*dt);var life=A[6]*(rain&&A[1]!=='r'?0.5:1)*(hot&&A[5]>0?0.7:1)*(E.ws>8?0.6:1);C.m*=Math.exp(-dt/60/Math.max(5,life))*Math.pow(r0/C.r,0.5);
    if(A[5]>0){var G2=cbGround(),key=cbGK(C.x,C.y)+'|'+C.ag;G2[key]=(G2[key]||0)+C.m*0.04;}});
  if(L)G.cbx=L.filter(function(C){return C.m>0.02;});
  /* 地面污染衰減（半衰期約為持久時間的一半；雨水加速） */if(GR)Object.keys(GR).forEach(function(key){var ag=key.split('|')[2],A=CBA[ag];GR[key]*=Math.exp(-dt/3600/Math.max(0.5,A[5]*0.7)*(rain?1.5:1));if(GR[key]<0.01)delete GR[key];});
  cbExpose(dt);cbInfStep(dt);}
function cbAnyInf(){return G.units.some(function(u){return u.cbg&&u.cbg.inf&&u.cbg.inf.length||u.cbg&&u.cbg.cont>0.01||u.sick>0.5&&CBC[u.dzk];});}
function cbConc(x,y){var o={},any=false;(G.cbx||[]).forEach(function(C){var d=dist(x,y,C.x,C.y);if(d>C.r*1.6)return;var f=Math.exp(-2*(d/C.r)*(d/C.r)),c=C.m/Math.max(0.05,(C.r/400)*(C.r/400))*f;if(c>0.001){o[C.ag]=(o[C.ag]||0)+c;any=true;}});
  var G2=G.cbgr;if(G2){var k0=cbGK(x,y);Object.keys(CBA).forEach(function(ag){var v=G2[k0+'|'+ag];if(v>0.001){o[ag]=(o[ag]||0)+v*0.6;o['g_'+ag]=v;any=true;}});}return any?o:null;}
/* 警報與戴面具：第一次聞到後一段時間才戴上（年代越新越快；防護等級 4 時已戴） */
function cbMaskDelay(u){var y=uEra(u).y;return y>=1980?15:y>=1950?30:y>=1917?60:150;}
function cbExpose(dt){G.units.forEach(function(u){if(!onMap(u)||!isLeaf(u)||ST(u).dom!=='land'||u.men<1)return;var o=cbConc(u.x,u.y),g=u.cbg;if(!o){if(g&&g.on&&G.t-(g.onT||0)>1800&&cbMopp(u)<4)g.on=0;if(g&&g.cont>0)g.cont*=0.995;return;}g=cbGear(u);
    /* 警報：這一輪中戴上面具之前的那段時間沒有面具的保護 */var bare=1;if(!g.on&&g.mask>0){if(!g.alarm||G.t-g.alarm>3600){g.alarm=G.t;logE(u.side,'cbrn',uName(u)+'：「毒氣！」'+(cbMopp(u)>=4?'（已在防護狀態）':'——戴上防毒面具'),u.x,u.y,u.id);}bare=clamp(cbMaskDelay(u)/dt,0,1);g.on=1;g.onT=G.t;}else{bare=0;if(g.on)g.onT=G.t;}
    var sus=Math.max(0,u.men-(g.inf||[]).reduce(function(a,q){return a+q.n;},0)),hurt=0,bio=[];Object.keys(o).forEach(function(ag){if(ag.indexOf('g_')===0)return;var A=CBA[ag];if(!A)return;var P=cbProt(u,ag);if(bare>0){g.on=0;var P0=cbProt(u,ag);g.on=1;P=P0*bare+P*(1-bare);}var dose=o[ag]*dt/60*(1-P);if(dose<=0)return;g.dose+=dose;
      if(o['g_'+ag]&&A[5]>0)g.cont=Math.min(5,g.cont+o['g_'+ag]*0.02*(1-P));if(g.on&&g.filt>0)g.filt=Math.max(0,g.filt-dose*3);
      if(A[1]==='b'||A[1]==='m'&&A[10]){var vx=g.vax[A[10]],imm=vx!==undefined&&G.t-vx>=((CBVX[A[10]]||[0,0,7])[2]*86400);var inf=sus*(1-Math.exp(-dose*A[3]*0.15))*(imm?0.08:1);if(inf>0.05){bio.push([A[10],inf]);sus-=inf;}if(A[1]!=='m')return;}
      var cas=u.men*(1-Math.exp(-dose*A[3]*0.06));if(cas>0.01){var kind=ag==='sarin'||ag==='vx'?'nerve':A[12]?A[12]:A[1]==='r'?'rad':A[1]==='m'?'mias':'gas',src=(G.cbx||[]).filter(function(C){return C.ag===ag;})[0];hit(u,src&&src.src?uById(src.src):null,cas,0,6+cas/Math.max(1,u.men)*80,kind);hurt+=cas;}});
    bio.forEach(function(q){g.inf.push({dz:q[0],n:q[1],t:G.t+(CBINC[q[0]]||(q[0]==='anth'?2:q[0]==='mias'?1:q[0]==='plag'?3:10))*86400*(0.6+0.8*rnd8())});});
    if(hurt>0.5&&!g.hurtLog){g.hurtLog=1;logE(u.side,'cbrn',uName(u)+'遭'+Object.keys(o).filter(function(k){return k.indexOf('g_')<0&&CBA[k];}).map(function(k){return CBA[k][0];}).join('、')+'侵襲（'+placeTxt(u.x,u.y)+'），出現傷亡'+(g.on?'':'（來不及戴上面具）'),u.x,u.y,u.id);}
    u.mor=clamp(u.mor-(g.on?0.3:1.5)*dt/60,0,100);});
  /* 平民 */if(G.civ&&G.cbx)G.cbx.forEach(function(C){var A=CBA[C.ag];if(A[1]==='c'||A[1]==='r'||A[1]==='m'){var c=C.m/Math.max(0.05,(C.r/400)*(C.r/400));if(c>0.05)civHit(C.x,C.y,C.r,clamp(0.004*c*A[4]*dt/60,0,0.05),'cbrn',C.side,A[4]>0.3?0.6:0.2);}});}
/* 潛伏期滿發病（進入既有的疾病系統）；人傳人的疾病擴散到附近部隊，醫療單位的隔離與疫苗降低傳播 */
function cbInfStep(dt){G.units.forEach(function(u){var g=u.cbg;if(!g||!alive(u))return;if(g.inf&&g.inf.length){var keep=[];g.inf.forEach(function(q){if(G.t>=q.t){if(typeof sickAdd==='function')sickAdd(u,q.n,q.dz);if(!g.sickLog||G.t-g.sickLog>6*3600){g.sickLog=G.t;logE(u.side,'cbrn',uName(u)+'爆發'+(DZ[q.dz]?DZ[q.dz][0]:q.dz)+'（約 '+fmt(q.n)+' 人發病）',u.x,u.y,u.id);}}else keep.push(q);});g.inf=keep;}
    if(g.cont>0.01&&onMap(u)){var P=Math.max(cbProt(u,'must'),cbMopp(u)>=3?0.8:0);var cas=u.men*(1-Math.exp(-g.cont*0.004*dt/60*(1-P)));if(cas>0.01)hit(u,null,cas,0,0.5,'gas');g.cont*=0.998;}});
  G.units.forEach(function(u){if(!isLeaf(u)||!onMap(u)||!(u.sick>0.5)||!CBC[u.dzk])return;var med=G.units.some(function(q){return q.side===u.side&&onMap(q)&&isLeaf(q)&&ST(q).fl.indexOf('D')>=0&&dist(q.x,q.y,u.x,u.y)<3000;}),beta=0.15*u.sick/Math.max(1,u.men+u.sick)*(u.quar?0.08:med?0.4:1)*dt/3600;
    cbNear(u.x,u.y,1500,function(t){if(t===u||!isLeaf(t)||!onMap(t)||ST(t).dom!=='land'||t.men<1)return;var g=cbGear(t),vx=g.vax[u.dzk],imm=vx!==undefined&&G.t-vx>=((CBVX[u.dzk]||[0,0,7])[2]*86400);var sus2=Math.max(0,t.men-g.inf.reduce(function(a,q){return a+q.n;},0)),n=sus2*beta*(imm?0.05:1)*(t.side===u.side?1:0.5);if(n>0.02)g.inf.push({dz:u.dzk,n:n,t:G.t+(4+4*rnd8())*86400});});
    if(G.civ&&!u.quar&&rnd8()<0.05){var gS=civAt?civAt(u.x,u.y,2000):null;if(gS)civHit(gS.x,gS.y,gS.r||800,0.0005,'dz',-1,0.3);}});}
/* ---------- 施放 ---------- */
/* 砲兵：命令帶毒劑時，每一輪射擊在彈著區產生毒劑雲（毒劑彈的炸藥較少，破片殺傷降為四分之一） */
(function(){var b=artyFire;artyFire=function(u,s,M){var o=u.ord,ag=o&&o.agent&&CBA[o.agent]?o.agent:null;if(!ag||M.kind!=='bombard')return b(u,s,M);var m0=M.mul;M.mul=(m0||1)*0.25;try{b(u,s,M);}finally{M.mul=m0;}
  var vol=Math.max(0.2,Math.sqrt(s.sa||1)*0.25*strFrac(u)),j=M.r*0.6;cbRelease(u.side,ag,M.x+(rnd8()-0.5)*j,M.y+(rnd8()-0.5)*j,vol,Math.max(150,M.r*0.8),u,o.cbLog?'持續施放':'以砲彈施放');o.cbLog=1;u.ammo=Math.max(0,u.ammo-0.4);};})();
/* 飛機：帶毒劑的打擊命令，飛臨目標上空時噴灑或投下毒劑彈（每架次一次） */
function cbAirStep(){G.units.forEach(function(u){var o=u.ord;if(!o||!o.agent||!CBA[o.agent]||o.cbDone||u.st!=='air'||ST(u).dom!=='air')return;if(o.x===undefined||dist(u.x,u.y,o.x,o.y)>1500)return;o.cbDone=1;var n=Math.max(1,u.veh);cbRelease(u.side,o.agent,o.x,o.y,0.6*n,700+n*40,u,'由空中噴灑');});}
/* 工兵：鋼瓶施放（第一次世界大戰的方式）：順風把毒氣雲吹向敵陣 */
function cbCylinder(u,ag,tx,ty){var E=G.env;windInit();var dirT=Math.atan2(ty-u.y,tx-u.x),dd=Math.abs(((dirT-E.wd+3*PI)%(2*PI))-PI);if(dd>PI/3)return {err:'風向不利（目前'+windTxt()+'），毒氣會吹回本方陣地'};if(E.ws<1)return {err:'風力太弱，毒氣會滯留在本方陣地'};
  var fw=frontW(u)||800,nx=-Math.sin(E.wd),ny=Math.cos(E.wd);for(var i=-2;i<=2;i++)cbRelease(u.side,ag,u.x+nx*fw*i/5+Math.cos(E.wd)*200,u.y+ny*fw*i/5+Math.sin(E.wd)*200,1.2,300,u,'以鋼瓶施放');u.fired=G.t;return {ok:1};}
/* 古代：投石機拋射疫屍到城內或敵營 */
function cbCatapult(u,tx,ty){if(dist(u.x,u.y,tx,ty)>(ST(u).ind||400)*1.05)return {err:'超出投射距離'};cbRelease(u.side,'corpse',tx,ty,0.8,200,u,'拋射疫屍');u.fired=G.t;return {ok:1};}
/* 半徑超過快速網格範圍時直接逐一檢查 */
function cbNear(x,y,R,fn){if(R<=GFR&&G._gf){gridNear(x,y,R,fn);return;}G.units.forEach(function(u){if(Math.abs(u.x-x)<=R&&Math.abs(u.y-y)<=R)fn(u);});}
/* ---------- 應對：除污、接種、隔離 ---------- */
function cbDecon(u,x,y,R){R=R||600;var G2=cbGround(),n=0,B=G.map.cs*8;Object.keys(G2).forEach(function(key){var p=key.split('|'),cx=(+p[0]+0.5)*B,cy=(+p[1]+0.5)*B;if(dist(cx,cy,x,y)<=R+B*0.7){G2[key]*=0.5;if(G2[key]<0.01)delete G2[key];n++;}});
  var m=0;cbNear(x,y,R,function(t){if(t.side!==u.side||!t.cbg||dist(t.x,t.y,x,y)>R)return;if(t.cbg.cont>0.01){t.cbg.cont*=0.3;m++;}t.cbg.filt=Math.min(100,t.cbg.filt+40);});return {ground:n,units:m};}
function cbVax(u,dz,R){R=R||4000;var V=CBVX[dz];if(!V)return {err:'沒有這種疫苗'};var y=uEra(u).y;if(dz==='mias'?!uEra(u).fan:y<V[1])return {err:'這個年代還沒有'+V[0]};var n=0;cbNear(u.x,u.y,R,function(t){if(t.side!==u.side||!isLeaf(t)||!alive(t)||dist(t.x,t.y,u.x,u.y)>R)return;var g=cbGear(t);if(g.vax[dz]===undefined){g.vax[dz]=G.t;n++;}});
  logE(u.side,'cbrn',uName(u)+'為附近 '+n+' 個單位接種'+V[0]+'（約 '+V[2]+' 天後產生免疫）',u.x,u.y,u.id);return {n:n};}
/* 工兵、醫療單位就地除污：每 10 分鐘一輪，最多約兩小時；移動時中止 */
function cbDeconStart(u){if(!u||!isLeaf(u)||!onMap(u))return false;u.cbDec={x:u.x,y:u.y,n:0};logE(u.side,'cbrn',uName(u)+'開始就地除污（'+placeTxt(u.x,u.y)+'）',u.x,u.y,u.id);return true;}
function cbOrdStep(){G.units.forEach(function(u){var D=u.cbDec;if(!D||!onMap(u))return;if(dist(u.x,u.y,D.x,D.y)>300){u.cbDec=null;logE(u.side,'cbrn',uName(u)+'離開，除污中止',u.x,u.y,u.id);return;}var r=cbDecon(u,D.x,D.y,700);D.n++;
  if(D.n>=12||r.ground===0&&r.units===0&&D.n>2){u.cbDec=null;logE(u.side,'cbrn',uName(u)+'完成除污',D.x,D.y,u.id);}});}
/* ---------- AI：依政策使用化學武器；受威脅時提高防護等級並除污 ---------- */
function cbPolicy(side){return polSide(side).cbrn||'no';}
function cbAI(){[0,1].forEach(function(side){var S=SD(side);if(!S.ai)return;var used=G.cbUse&&G.cbUse[1-side],pol=cbPolicy(side);
  if(used&&G.t-used<86400&&!S.moppSet&&(S.mopp||0)<2){S.mopp=2;logE(side,'cbrn','敵軍使用了化生放武器：全軍提高防護等級（MOPP 2）');}
  if(!(pol==='yes'||pol==='retal'&&used))return;if(G.t-(S._cbT||-1e9)<3*3600)return;var av=cbAvail(side).filter(function(k){return CBA[k][1]==='c';});if(!av.length)return;var ag=av[av.length-1];
  var C=G.ct[side],best=null,bv=0;for(var id in C){var c=C[id];if(c.dead||G.t-c.t>1800||c.dom!=='land')continue;var v=(c.men||0)*((uById(c.id)||{}).ent>0.5?1.6:1);if(v>bv&&enemyNear(1-side,c.x,c.y,2500,'land')===0){bv=v;best=c;}}if(!best||bv<150)return;
  var A=G.units.filter(function(u){return u.side===side&&isLeaf(u)&&onMap(u)&&aiControls(u)&&(ST(u).ind||0)>0&&dist(u.x,u.y,best.x,best.y)<=(ST(u).ind||0)*0.95&&u.ammo>30;}).slice(0,2);if(!A.length)return;S._cbT=G.t;
  A.forEach(function(u){issue(u,'bombard',{x:best.x,y:best.y,agent:ag,dur:900});});logE(side,'cbrn','指揮部下令以'+CBA[ag][0]+'砲擊'+placeTxt(best.x,best.y)+'的敵軍');});}
(function(){var b=v8Step;v8Step=function(){b();if(!cbOn())return;if(G.step%60===5)windStep();if(G.step%4===2){cbrnStep();cbAirStep();}if(G.step%20===13)cbOrdStep();if(G.step%120===37)cbAI();};})();
/* 防護等級的代價：防護等級 3 以上更容易疲勞（炎熱時加倍），4 級戰鬥力降低 */
(function(){var b=firerMod;firerMod=function(u,s){var f=b(u,s);if(u.cbg&&(u.cbg.on||cbMopp(u)>=4))f*=cbMopp(u)>=4?0.75:0.88;return f;};})();
(function(){var b=v8Step;v8Step=function(){b();if(G.step%20!==3)return;G.units.forEach(function(u){if(!u.cbg||!onMap(u))return;var M=cbMopp(u);if(M>=3||u.cbg.on)u.fat=Math.min(100,u.fat+(M>=4?1.2:0.5)*(G.env.T>25?2:1));});};})();

